{
  "name": "opencode-file-browser",
  "version": "1.0.0",
  "description": "Arrow-key file browser and project-scoped file tools for the opencode TUI.",
  "type": "module",
  "exports": {
    "./server": "./src/index.ts",
    "./tui": "./src/tui.ts"
  },
  "files": [
    "src",
    "assets",
    "install.ps1",
    "install.sh",
    "README.md",
    "CONTRIBUTING.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "file-browser",
    "file-manager",
    "file-tree",
    "tui",
    "terminal-ui",
    "cli",
    "developer-tools",
    "ai-agent",
    "ai-coding",
    "typescript"
  ],
  "license": "MIT",
  "author": "MeanLesss",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MeanLesss/opencode-file-browser.git"
  },
  "bugs": {
    "url": "https://github.com/MeanLesss/opencode-file-browser/issues"
  },
  "homepage": "https://github.com/MeanLesss/opencode-file-browser#readme",
  "engines": {
    "opencode": ">=1.19.5 <2"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.19.5"
  },
  "devDependencies": {
    "@types/node": "^24.12.2",
    "typescript": "^5.8.3"
  }
}
